using IndieRun;
using System.IO;
using System.Diagnostics;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Threading;
using System.Xml.Linq;

static class Program
{
    static void Check(bool yes,string text){if(!yes)throw new Exception(text);}
    static object? Call(object o,string name,params object?[] args)=>o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static T Get<T>(object o,string name)=>(T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.GetValue(o)!;
    static void Set(object o,string name,object? value)=>o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.SetValue(o,value);
    static T Copy<T>(T item)=>JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(item))!;
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Refuse(Action run){try{run();}catch(Exception ex)when(ex is IOException or InvalidDataException or UnauthorizedAccessException or ArgumentException or JsonException){return;}throw new Exception("Expected refusal");}
    static Package Game(string root,string relative="input/Product/Game",bool added=true)
    {var path=Path.GetFullPath(Path.Combine(root,relative));Directory.CreateDirectory(Path.Combine(path,"Runtime"));File.WriteAllText(Path.Combine(path,"Game.exe"),"generated fixture; do not execute");File.WriteAllText(Path.Combine(path,"Runtime","data.bin"),"fixture data");return new(){Registered=added,IsReal=true,Id=Guid.NewGuid().ToString("N"),Source=path,DetectedRoot=path,SearchRoot=Path.Combine(root,"input"),Name=Path.GetFileName(path),Folder=Path.GetFileName(path),Alias="내 게임",Genres=["퍼즐"]};}
    static (WorkspaceDocument Plan,PlayerDocument Play,TagCatalog Tags,LibraryDocument Library,Package Game) Fixture(string root,bool marker=true)
    {
        var p=Game(root);var library=Path.Combine(root,"library");var tags=new TagCatalog{Tags=[new(){Kind="genre",Name="퍼즐"},new(){Kind="category",Name="짧은 게임"}]};p.Categories=["짧은 게임"];p.GenreIds=[tags.Tags[0].Id];p.CategoryIds=[tags.Tags[1].Id];
        Directory.CreateDirectory(Path.Combine(root,"input/Product/Comics"));File.WriteAllText(Path.Combine(root,"input/Product/Comics/guide.txt"),"guide");
        var scan=GameScanner.Scan(p.SearchRoot);var lib=marker?new LibraryStore(library).Register(p,tags.Tags,scan).Document:new LibraryDocument();scan=GameScanner.Scan(p.SearchRoot);
        var play=new PlayerDocument{Games=[new(){Id=p.Id,Executable="Game.exe",WorkingDirectory="Runtime",Arguments="--keep",Favorite=true,Hidden=true,CropX=.2,CropY=.8}]};
        var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=library,BackupRoot=Path.Combine(root,"backups"),SelectedId=p.Id,Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)],Tags=tags.Tags};return(plan,play,tags,lib,p);
    }
    static void Image(string root,GamePlay game)
    {var path=Path.Combine(root,".indierun-art","fixture.png");Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllBytes(path,Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jS9kAAAAASUVORK5CYII="));game.Image=".indierun-art/fixture.png";}
    static MainWindow Window(string root,List<Package> games)
    {
        var w=new MainWindow();var scan=GameScanner.Scan(Path.Combine(root,"input"));Set(w,"packages",games);Set(w,"selected",games[0]);Set(w,"snapshot",scan);Set(w,"source",Path.Combine(root,"input"));Set(w,"searchLocations",new List<SearchLocation>{new(){Path=Path.Combine(root,"input")}});Set(w,"destination",Path.Combine(root,"library"));Set(w,"playerRoot",Path.Combine(root,"library"));Set(w,"backupStorageRoot",Path.Combine(root,"backups"));Set(w,"checkpoints",games.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList());return w;
    }
    static void EnableSave(MainWindow w){Set(w,"workspaceLock",Get<WorkspaceStore>(w,"workspaceStore").AcquireLock());Set(w,"sessionReady",true);Set(w,"identityNoticeAccepted",true);}
    static void Close(MainWindow w){Set(w,"scopeDraft",null);Set(w,"closingWithoutSave",true);w.Close();}
    [STAThread] static int Main(string[] args)
    {
        if(args.Length>0&&args[0]=="--scope-child")
        {
            var service=new ScopeChange(args[1]);service.Checkpoint=stage=>{if(stage==args[3]){Console.WriteLine("READY");Console.Out.Flush();Thread.Sleep(Timeout.Infinite);}};
            service.Commit(JsonSerializer.Deserialize<ScopeChangeRecord>(File.ReadAllText(args[2]))!);return 0;
        }
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(app.Dispatcher));
        var root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> run){var folder=Path.Combine(root,name);Directory.CreateDirectory(folder);try{run(folder);results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,status="FAIL",error=ex.ToString()});Console.WriteLine("FAIL "+name+": "+ex.Message);}}
        Test("mixed-selection-uses-one-intake-action",folder=>{var a=Game(folder,added:false);var b=Game(folder,"input/Second",true);var w=Window(folder,[a,b]);try{Call(w,"PickAll_Click",w,new RoutedEventArgs());Check(Get<HashSet<string>>(w,"organizeSelection").Count==2,"Registered game not selectable");Check(Get<Button>(w,"AddGamesButton").Content as string=="게임 가져오기"&&Get<Button>(w,"AddGamesButton").Visibility==Visibility.Visible&&Get<Button>(w,"MovePickedButton").Visibility==Visibility.Collapsed&&Get<TextBlock>(w,"PlanCount").Text=="2개 선택","Mixed selection lost its single intake action");var selection=new IntakeSelection(new MoveSelection(new[]{a,b},new[]{a,b}));Check(selection.Games.Count==2,"Mixed intake lost a game");Call(w,"ClearPicked_Click",w,new RoutedEventArgs());Check(Get<HashSet<string>>(w,"organizeSelection").Count==0,"Selection not cleared");}finally{Close(w);}});
        Test("select-all-respects-search-and-review-state",folder=>{var a=Game(folder);var b=Game(folder,"input/Second");b.Alias="다른 게임";b.ReviewState="missing";var w=Window(folder,[a,b]);try{Get<TextBox>(w,"Search").Text="내 게임";Call(w,"PickAll_Click",w,new RoutedEventArgs());Check(Get<HashSet<string>>(w,"organizeSelection").SetEquals([a.Id]),"Invisible or blocked game selected");}finally{Close(w);}});
        Test("registered-scope-preview-and-cancel-never-write-markers",folder=>{var f=Fixture(folder);var w=Window(folder,[f.Game]);try{Call(w,"EditScope_Click",w,new RoutedEventArgs());Call(w,"DraftScope",Path.Combine(folder,"input/Product"),true);Check(f.Game.Source==f.Game.DetectedRoot&&LibraryStore.ReadIdentity(f.Game.Source)!.GameId==f.Game.Id&&!File.Exists(Path.Combine(folder,"input/Product",LibraryStore.MarkerName)),"Preview changed identity");Call(w,"CancelScope_Click",w,new RoutedEventArgs());Check(Get<Package?>(w,"scopeDraft")==null&&f.Game.Source==f.Game.DetectedRoot,"Cancel changed scope");}finally{Close(w);}});
        Test("registered-expand-and-shrink-preserve-absolute-execution-and-metadata",folder=>
        {
            var f=Fixture(folder);var service=new ScopeChange(Path.Combine(folder,"data"));var old=f.Game.Source;var target=Path.GetFullPath(Path.Combine(folder,"input/Product"));var bytes=File.ReadAllBytes(Path.Combine(old,"Game.exe"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,target);service.Commit(r);
            var saved=new WorkspaceStore(Path.Combine(folder,"data/workspace.json")).Load().Document!;var play=new PlayerStore(f.Plan.Destination).Load();var p=saved.Packages.Single();Check(p.Source==target&&p.Alias=="내 게임"&&p.Genres.Contains("퍼즐"),"Metadata lost");Check(play.Games[0].Executable==Path.Combine("Game","Game.exe")&&play.Games[0].WorkingDirectory==Path.Combine("Game","Runtime")&&play.Games[0].Favorite&&play.Games[0].Hidden&&play.Games[0].Arguments=="--keep","Launch not rebased");Check(!File.Exists(Path.Combine(old,LibraryStore.MarkerName))&&LibraryStore.ReadIdentity(target)!.GameId==p.Id&&File.ReadAllBytes(Path.Combine(old,"Game.exe")).SequenceEqual(bytes),"Game files changed");
            var lib=new LibraryStore(f.Plan.Destination).Load();var shrink=service.Prepare(saved,f.Tags,play,lib,p.Id,old);service.Commit(shrink);Check(new PlayerStore(f.Plan.Destination).Load().Games[0].Executable=="Game.exe"&&LibraryStore.ReadIdentity(old)!.GameId==p.Id&&!File.Exists(Path.Combine(target,LibraryStore.MarkerName)),"Shrink failed");
        });
        Test("scope-shrink-follows-configured-launcher-instead-of-first-detected-exe",folder=>
        {
            var f=Fixture(folder);var data=Path.Combine(folder,"data");var service=new ScopeChange(data);var expanded=service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product"));service.Commit(expanded);var plan=new WorkspaceStore(Path.Combine(data,"workspace.json")).Load().Document!;
            var alt=Path.GetFullPath(Path.Combine(folder,"input/Product/Alternative"));Directory.CreateDirectory(alt);File.WriteAllText(Path.Combine(alt,"Game64.exe"),"fixture");var play=new PlayerStore(f.Plan.Destination).Load();play.Games[0].Executable=Path.Combine("Alternative","Game64.exe");play.Games[0].WorkingDirectory="Alternative";
            var record=service.Prepare(plan,f.Tags,play,new LibraryStore(f.Plan.Destination).Load(),f.Game.Id,alt);service.Commit(record);Check(new PlayerStore(f.Plan.Destination).Load().Games[0].Executable=="Game64.exe"&&LibraryStore.ReadIdentity(alt)!.GameId==f.Game.Id,"Configured launcher was excluded");
        });
        Test("new-scope-journal-does-not-fall-back-to-previous-transaction",folder=>
        {
            var f=Fixture(Path.Combine(folder,"first"));var service=new ScopeChange(Path.Combine(folder,"data"));service.Commit(service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"first/input/Product")));
            var next=Fixture(Path.Combine(folder,"second"));var record=service.Prepare(next.Plan,next.Tags,next.Play,next.Library,next.Game.Id,Path.Combine(folder,"second/input/Product"));service.Checkpoint=stage=>{if(stage=="intent")throw new IOException("stop");};Refuse(()=>service.Commit(record));File.WriteAllText(service.Pending,"broken new transaction");Refuse(()=>new ScopeChange(Path.Combine(folder,"data")).Recover());Check(LibraryStore.ReadIdentity(next.Game.Source)!.GameId==next.Game.Id,"Recovered unrelated previous transaction");
        });
        Test("shrink-refuses-excluded-working-folder-before-any-write",folder=>{var f=Fixture(folder);f.Play.Games[0].WorkingDirectory=".";var service=new ScopeChange(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product"));service.Commit(r);var saved=new WorkspaceStore(Path.Combine(folder,"data/workspace.json")).Load().Document!;var play=new PlayerStore(f.Plan.Destination).Load();play.Games[0].WorkingDirectory=".";Refuse(()=>service.Prepare(saved,f.Tags,play,new LibraryStore(f.Plan.Destination).Load(),f.Game.Id,f.Game.Source));Check(!service.HasPending,"Invalid scope wrote journal");});
        Test("scope-refuses-overlap-and-foreign-marker",folder=>{var f=Fixture(folder);var other=Game(folder,"input/Product/Other");other.Excluded=true;f.Plan.Packages.Add(other);var service=new ScopeChange(Path.Combine(folder,"data"));Refuse(()=>service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product")));f.Plan.Packages.Remove(other);LibraryStore.EnsureIdentity(Path.Combine(folder,"input/Product"),Guid.NewGuid().ToString("N"));Refuse(()=>service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product")));Check(LibraryStore.ReadIdentity(f.Game.Source)!.GameId==f.Game.Id,"Old ID changed");});
        foreach(var stop in new[]{"intent","new-marker","old-marker-removed","metadata"})Test("scope-crash-recovery-"+stop,folder=>{var f=Fixture(folder);var data=Path.Combine(folder,"data");var service=new ScopeChange(data);var record=service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product"));service.Checkpoint=stage=>{if(stage==stop)throw new IOException("simulated interruption");};Refuse(()=>service.Commit(record));Check(service.HasPending,"Journal missing");new ScopeChange(data).Recover();Check(!service.HasPending&&LibraryStore.ReadIdentity(record.NewRoot)!.GameId==f.Game.Id&&!File.Exists(Path.Combine(record.OldRoot,LibraryStore.MarkerName)),"Recovery did not converge");Check(new WorkspaceStore(Path.Combine(data,"workspace.json")).Load().Document!.Packages[0].Source==record.NewRoot,"Wrong restored scope");});
        foreach(var stop in new[]{"new-marker","metadata"})Test("actual-process-kill-scope-recovery-"+stop,folder=>
        {
            var f=Fixture(folder);var data=Path.Combine(folder,"data");var service=new ScopeChange(data);var record=service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product"));var recordPath=Path.Combine(folder,"record.json");File.WriteAllText(recordPath,JsonSerializer.Serialize(record));
            var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"--scope-child",data,recordPath,stop})start.ArgumentList.Add(arg);
            using(var process=Process.Start(start)!){try{var line=process.StandardOutput.ReadLineAsync().WaitAsync(TimeSpan.FromSeconds(25)).GetAwaiter().GetResult();Check(line=="READY","Child did not reach checkpoint");process.Kill(true);Check(process.WaitForExit(10000),"Child did not stop");}finally{if(!process.HasExited)process.Kill(true);}}
            service.Recover();Check(!service.HasPending&&LibraryStore.ReadIdentity(record.NewRoot)!.GameId==f.Game.Id&&!File.Exists(Path.Combine(record.OldRoot,LibraryStore.MarkerName)),"Killed operation did not recover");
        });
        Test("locked-csv-keeps-scope-intent-and-recovers",folder=>{var f=Fixture(folder);var data=Path.Combine(folder,"data");var service=new ScopeChange(data);var record=service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product"));using(var held=new FileStream(Path.Combine(f.Plan.Destination,LibraryStore.CsvName),FileMode.Open,FileAccess.ReadWrite,FileShare.None))Refuse(()=>service.Commit(record));Check(service.HasPending&&File.Exists(new EditTransaction(data).Pending),"Interrupted edit not recorded");service.Recover();Check(!service.HasPending&&!File.Exists(new EditTransaction(data).Pending),"Locked CSV recovery failed");});
        Test("changed-game-file-during-scope-recovery-is-preserved",folder=>{var f=Fixture(folder);var service=new ScopeChange(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product"));service.Checkpoint=stage=>{if(stage=="intent")throw new IOException("stop");};Refuse(()=>service.Commit(r));File.WriteAllText(Path.Combine(f.Game.Source,"Game.exe"),"user changed file");Refuse(()=>new ScopeChange(Path.Combine(folder,"data")).Recover());Check(File.ReadAllText(Path.Combine(f.Game.Source,"Game.exe"))=="user changed file"&&service.HasPending,"Recovery changed user file");});
        Test("local-registration-scope-never-creates-a-marker",folder=>{var f=Fixture(folder,false);f.Game.LocalRegistration=true;var service=new ScopeChange(Path.Combine(folder,"data"));var r=service.Prepare(f.Plan,f.Tags,f.Play,f.Library,f.Game.Id,Path.Combine(folder,"input/Product"));service.Commit(r);Check(!Directory.GetFiles(Path.Combine(folder,"input"),LibraryStore.MarkerName,SearchOption.AllDirectories).Any(),"Local scope wrote marker");});
        Test("invalid-scope-record-fails-without-touching-files",folder=>{var data=Path.Combine(folder,"data");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"scope-pending.json"),"{\"Version\":1,\"Bundle\":null}");Refuse(()=>new ScopeChange(data).Recover());Check(File.Exists(Path.Combine(data,"scope-pending.json")),"Bad record removed");});
        Test("portable-roundtrip-preserves-tags-settings-and-image",folder=>
        {
            var f=Fixture(folder);Image(f.Plan.Destination,f.Play.Games[0]);PortableStore.Export(Path.GetDirectoryName(f.Game.Source)!,f.Game.Folder,f.Game,f.Play.Games[0],f.Tags,f.Plan.Destination);var record=PortableStore.Read(f.Game.Source)!;var target=Copy(f.Game);target.Alias="";target.Genres=[];target.Categories=[];var tags=new TagCatalog();var restored=PortableStore.Import(record,target,tags,Path.Combine(folder,"fresh-settings"));Check(target.Alias=="내 게임"&&target.Genres.Contains("퍼즐")&&target.Categories.Contains("짧은 게임")&&restored.Favorite&&restored.Hidden&&restored.Arguments=="--keep"&&restored.Executable=="Game.exe"&&restored.CropY==.8,"Roundtrip lost metadata");Check(File.ReadAllBytes(Path.Combine(folder,"fresh-settings",restored.Image)).SequenceEqual(File.ReadAllBytes(Path.Combine(f.Plan.Destination,f.Play.Games[0].Image))),"Image lost");
        });
        Test("portable-folder-rename-uses-id-instead-of-name",folder=>{var f=Fixture(folder);PortableStore.Export(Path.GetDirectoryName(f.Game.Source)!,f.Game.Folder,f.Game,f.Play.Games[0],f.Tags,f.Plan.Destination);var renamed=f.Game.Source+"-renamed";Directory.Move(f.Game.Source,renamed);Check(PortableStore.Read(renamed)!.Id==f.Game.Id,"Name used as identity");});
        Test("portable-tag-collision-keeps-existing-definition",folder=>{var f=Fixture(folder);PortableStore.Export(Path.GetDirectoryName(f.Game.Source)!,f.Game.Folder,f.Game,f.Play.Games[0],f.Tags,f.Plan.Destination);var tags=new TagCatalog{Tags=[new(){Id=f.Tags.Tags[0].Id,Kind="category",Name="기존 분류"}]};var imported=Copy(f.Game);PortableStore.Import(PortableStore.Read(f.Game.Source)!,imported,tags,Path.Combine(folder,"new"));Check(tags.Tags.Single(t=>t.Id==f.Tags.Tags[0].Id).Name=="기존 분류"&&imported.GenreIds.Single()!=f.Tags.Tags[0].Id,"Existing tag overwritten");});
        Test("portable-corrupt-and-foreign-records-are-not-overwritten",folder=>{var f=Fixture(folder);var parent=Path.GetDirectoryName(f.Game.Source)!;PortableStore.Export(parent,f.Game.Folder,f.Game,f.Play.Games[0],f.Tags,f.Plan.Destination);var path=Path.Combine(parent,PortableStore.DirectoryName,f.Game.Id,"game.json");File.WriteAllText(path,"foreign data");Refuse(()=>PortableStore.Export(parent,f.Game.Folder,f.Game,f.Play.Games[0],f.Tags,f.Plan.Destination));Check(File.ReadAllText(path)=="foreign data","Foreign document overwritten");});
        Test("portable-image-traversal-and-corruption-refused-before-metadata-change",folder=>{var f=Fixture(folder);Image(f.Plan.Destination,f.Play.Games[0]);PortableStore.Export(Path.GetDirectoryName(f.Game.Source)!,f.Game.Folder,f.Game,f.Play.Games[0],f.Tags,f.Plan.Destination);var record=PortableStore.Read(f.Game.Source)!;var p=Copy(f.Game);p.Alias="사용자 정보";record.Artwork="../outside.png";Refuse(()=>PortableStore.Import(record,p,new TagCatalog(),Path.Combine(folder,"fresh")));Check(p.Alias=="사용자 정보","Metadata partially changed");});
        Test("portable-metadata-directory-is-not-discovered-as-game",folder=>{var f=Fixture(folder);var fake=Path.Combine(f.Game.SearchRoot,PortableStore.DirectoryName,"fake");Directory.CreateDirectory(fake);File.WriteAllText(Path.Combine(fake,"Bad.exe"),"fixture");var scan=GameScanner.Scan(f.Game.SearchRoot);Check(!scan.Files.Any(x=>GameScanner.Within(x.Path,fake)),"Internal metadata scanned");});
        Test("bulk-move-backs-up-both-and-writes-portable-information",folder=>
        {
            var a=Game(folder,"input/One");var b=Game(folder,"input/Two");b.Alias="다른 게임";var w=Window(folder,[a,b]);try{EnableSave(w);Set(w,"catalog",new TagCatalog());Set(w,"playerDocument",new PlayerDocument{Games=[new(){Id=a.Id,Executable="Game.exe",Arguments="--one"},new(){Id=b.Id,Executable="Game.exe",Favorite=true}]});var target=Path.Combine(folder,"target");Wait((Task)Call(w,"StartMoveBatchAsync",new List<Package>{a,b},target)!);var service=new BackupEngine(Path.Combine(folder,"backups"));Check(service.ListJobs().Count==2&&service.ListMoves().All(m=>m.Status=="Completed"),"Bulk move did not finish");Check(PortableStore.Read(Path.Combine(target,"One"))!.Play.Arguments=="--one"&&PortableStore.Read(Path.Combine(target,"Two"))!.Play.Favorite,"Portable metadata lost in move");}finally{Close(w);}
        });
        Test("automatic-portable-import-restores-new-game-without-overwriting-known-game",folder=>{var f=Fixture(folder);PortableStore.Export(Path.GetDirectoryName(f.Game.Source)!,f.Game.Folder,f.Game,f.Play.Games[0],f.Tags,f.Plan.Destination);var w=Window(folder,[f.Game]);try{f.Game.Alias="";Set(w,"destination",Path.Combine(folder,"fresh"));Set(w,"playerRoot",Path.Combine(folder,"fresh"));Call(w,"ImportPortableGames",new HashSet<string>(),GameScanner.Scan(f.Game.SearchRoot));Check(f.Game.Alias=="내 게임"&&Get<PlayerDocument>(w,"playerDocument").Games.Single().Favorite,"Auto import failed");Check(new LibraryStore(Path.Combine(folder,"fresh")).Load().Games.Single().Alias=="내 게임","Imported game missing from library metadata");f.Game.Alias="사용자 수정";Call(w,"ImportPortableGames",new HashSet<string>{f.Game.Id},GameScanner.Scan(f.Game.SearchRoot));Check(f.Game.Alias=="사용자 수정","Known game overwritten");}finally{Close(w);}});
        Test("existing-library-metadata-is-not-replaced-by-an-older-portable-copy",folder=>{var f=Fixture(folder);PortableStore.Export(Path.GetDirectoryName(f.Game.Source)!,f.Game.Folder,f.Game,f.Play.Games[0],f.Tags,f.Plan.Destination);var w=Window(folder,[f.Game]);try{f.Game.Alias="현재 별칭";Set(w,"libraryDocument",f.Library);Call(w,"ImportPortableGames",new HashSet<string>(),GameScanner.Scan(f.Game.SearchRoot));Check(f.Game.Alias=="현재 별칭","Existing metadata overwritten");}finally{Close(w);}});
        foreach(var size in new[]{(1090d,720d),(1350d,870d)})Test("mixed-footer-layout-"+size.Item1,folder=>{var a=Game(folder,added:false);var b=Game(folder,"input/Second",true);var w=Window(folder,[a,b]);try{Call(w,"PickAll_Click",w,new RoutedEventArgs());var root=(Grid)w.Content;root.Measure(new Size(size.Item1,size.Item2));root.Arrange(new Rect(0,0,size.Item1,size.Item2));root.UpdateLayout();var add=Get<Button>(w,"AddGamesButton");var move=Get<Button>(w,"MovePickedButton");var ap=add.TranslatePoint(new Point(),root);var mp=move.TranslatePoint(new Point(),root);Check(mp.X+move.ActualWidth<=ap.X&&ap.X+add.ActualWidth<=size.Item1+.5&&ap.Y+add.ActualHeight<=size.Item2+.5,"Footer actions overlap");}finally{Close(w);}});
        foreach(var size in new[]{(1090d,720d),(1350d,870d)})Test("scope-footer-layout-"+size.Item1,folder=>{var f=Fixture(folder);var w=Window(folder,[f.Game]);try{Set(w,"playerDocument",f.Play);Call(w,"EditScope_Click",w,new RoutedEventArgs());Call(w,"DraftScope",Path.GetDirectoryName(f.Game.Source)!,true);var root=(Grid)w.Content;root.Measure(new Size(size.Item1,size.Item2));root.Arrange(new Rect(0,0,size.Item1,size.Item2));root.UpdateLayout();var apply=Get<Button>(w,"ApplyScopeButton");var cancel=Get<Button>(w,"CancelScopeButton");var ap=apply.TranslatePoint(new Point(),root);var cp=cancel.TranslatePoint(new Point(),root);Check(apply.Visibility==Visibility.Visible&&apply.IsEnabled&&cancel.Visibility==Visibility.Visible,"Scope actions missing");Check(cp.X+cancel.ActualWidth<=ap.X&&ap.X+apply.ActualWidth<=size.Item1+.5&&ap.Y+apply.ActualHeight<=size.Item2+.5,"Scope footer overlaps");Check(Get<Button>(w,"AddGamesButton").Visibility==Visibility.Collapsed&&Get<Button>(w,"OrganizeInfoButton").Visibility==Visibility.Collapsed,"Unrelated actions remain visible");}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{root,total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"RESULT {results.Count-failed}/{results.Count}");return failed==0?0:1;
    }
}
